async def execute_tools(
    message: ChatCompletionMessage,
    registry: Any,
    tracker: ToolCallTracker | None = None,
    tool_timeout: float = 300.0,
    *,
    trace: AgentTrace | None = None,
    turn: int | None = None,
) -> list[dict[str, Any]]:
    """按顺序执行 function calls，并生成匹配的 tool messages。"""
    if tool_timeout <= 0:
        raise ValueError("tool_timeout 必须大于 0")

    tool_results: list[dict[str, Any]] = []
    tool_calls = message.tool_calls or []
    for tool_call in tool_calls:
        name = tool_call.function.name
        trace_context = (
            trace.event_context(turn) if trace is not None else None
        )
        try:
            input_data = json.loads(tool_call.function.arguments or "{}")
            if not isinstance(input_data, dict):
                raise TypeError("工具输入必须是 object")
        except (TypeError, json.JSONDecodeError) as exc:
            content = f"工具 {name} 参数 JSON 无效: {exc}"
            logger.error(
                content,
                extra={
                    "event": "agent.tool_invalid_arguments",
                    "trace": trace_context,
                    "data": {
                        "tool": name,
                        "status": "invalid_arguments",
                        "error": str(exc),
                    },
                },
            )
            tool_results.append(
                {
                    "role": "tool",
                    "tool_call_id": tool_call.id,
                    "content": content,
                }
            )
            continue

        if tracker is not None and not tracker.allow(name, input_data):
            content = (
                "检测到相同工具调用已连续重复 "
                f"{tracker.max_consecutive} 次，请停止重复调用并采取下一步行动。"
            )
            logger.warning(
                "拦截重复调用: %s %s",
                name,
                input_data,
                extra={
                    "event": "agent.tool_blocked",
                    "trace": trace_context,
                    "data": {
                        "tool": name,
                        "status": "blocked",
                        "arguments": input_data,
                    },
                },
            )
        else:
            logger.info(
                "工具开始: %s",
                name,
                extra={
                    "event": "agent.tool_started",
                    "trace": trace_context,
                    "console_message": f"调用工具: {name} {input_data}",
                    "data": {
                        "tool": name,
                        "arguments": input_data,
                    },
                },
            )
            try:
                execution = await asyncio.wait_for(
                    registry.execute_with_status(name, input_data),
                    timeout=tool_timeout,
                )
                content = execution.content
                status = "error" if execution.is_error else "ok"
            except TimeoutError:
                content = (
                    f"工具 {name} 执行超时（超过 {tool_timeout:g} 秒）"
                )
                status = "timeout"
            logger.info(
                "工具完成: %s (%s)",
                name,
                status,
                extra={
                    "event": "agent.tool_completed",
                    "trace": trace_context,
                    "console_message": f"工具结果: {content}",
                    "data": {
                        "tool": name,
                        "status": status,
                        "content": content,
                    },
                },
            )

        tool_results.append(
            {
                "role": "tool",
                "tool_call_id": tool_call.id,
                "content": content,
            }
        )
    return tool_results

"""维护可直接发送给 Chat Completions API 的完整对话历史。"""

from typing import Any


class Context:
    """保存 user、assistant 和 tool 消息，并校验工具调用配对。"""

    def __init__(self) -> None:
        self.messages: list[dict[str, Any]] = []

    def append_user(self, text: str) -> None:
        """追加用户文本消息。"""
        self.messages.append({"role": "user", "content": text})

    def append_assistant(self, message: dict[str, Any]) -> None:
        """追加完整 assistant 消息，包括 tool_calls。"""
        self.messages.append(message)

    def append_tool_results(self, tool_results: list[dict[str, Any]]) -> None:
        """追加与上一条 assistant tool_calls 对应的 tool 消息。"""
        self.messages.extend(tool_results)

    def assert_paired(self) -> None:
        """校验每个 assistant tool_call 都有唯一匹配的 tool result。"""
        pending_ids: set[str] = set()
        seen_ids: set[str] = set()

        for message in self.messages:
            role = message.get("role")
            if role not in {"user", "assistant", "tool"}:
                raise RuntimeError(f"未知消息角色: {role}")

            if role == "assistant":
                if pending_ids:
                    raise RuntimeError("上一轮 tool_calls 缺少对应的 tool result")
                for tool_call in message.get("tool_calls") or []:
                    tool_call_id = tool_call.get("id")
                    if not isinstance(tool_call_id, str) or not tool_call_id:
                        raise RuntimeError("tool_call 缺少有效 id")
                    if tool_call_id in seen_ids:
                        raise RuntimeError(f"tool_call id 重复: {tool_call_id}")
                    pending_ids.add(tool_call_id)
                    seen_ids.add(tool_call_id)
                continue

            if role == "user":
                if pending_ids:
                    raise RuntimeError("tool_calls 后出现了普通 user 消息")
                continue

            tool_call_id = message.get("tool_call_id")
            if not isinstance(tool_call_id, str) or not tool_call_id:
                raise RuntimeError("tool result 缺少有效 tool_call_id")
            if tool_call_id not in pending_ids:
                raise RuntimeError(
                    f"tool result 没有匹配的 tool_call: {tool_call_id}"
                )
            pending_ids.remove(tool_call_id)

        if pending_ids:
            missing = ", ".join(sorted(pending_ids))
            raise RuntimeError(f"对话结束时仍有未配对的 tool_call: {missing}")

    if isinstance(result, str):
        return result
    return json.dumps(result, ensure_ascii=False, default=str)


class ToolRegistry:
    """管理工具注册、schema 导出和执行。"""

    def __init__(self) -> None:
        self._tools: dict[str, RegisteredTool] = {}

    def register(
        self,
        handler: ToolHandler,
        *,
        name: str | None = None,
        description: str | None = None,
        input_schema: dict[str, Any] | None = None,
    ) -> ToolHandler:
        """注册工具，缺省信息从函数定义生成。"""
        tool_name = name or handler.__name__
        if tool_name in self._tools:
            raise ValueError(f"工具已注册: {tool_name}")
        generated_description, generated_schema = _build_definition(handler)
        self._tools[tool_name] = RegisteredTool(
            name=tool_name,
            description=description or generated_description,
            input_schema=input_schema or generated_schema,
            handler=handler,
        )
        return handler

    def tool(
        self,
        handler: ToolHandler | None = None,
        *,
        name: str | None = None,
        description: str | None = None,
        input_schema: dict[str, Any] | None = None,
    ) -> ToolHandler | Callable[[ToolHandler], ToolHandler]:
        """支持 `@tool` 和 `@tool(...)` 两种装饰器写法。"""
        def decorator(function: ToolHandler) -> ToolHandler:
            return self.register(
                function,
                name=name,
                description=description,
                input_schema=input_schema,
            )

        if handler is None:
            return decorator
        return decorator(handler)

    def schemas(self) -> list[dict[str, Any]]:
        """导出 Messages API 使用的工具 schema。"""
        return [
            {
                "name": registered.name,
                "description": registered.description,
                "input_schema": deepcopy(registered.input_schema),
            }
            for registered in self._tools.values()
        ]

    async def execute_with_status(
        self,
        name: str,
        input_data: dict[str, Any],
    ) -> ToolExecutionResult:
        """执行工具；异常转成 is_error 结果供模型继续处理。"""
        try:
            if not isinstance(input_data, dict):
                raise TypeError("工具输入必须是 object")
            if name not in self._tools:
                raise KeyError(f"未注册工具: {name}")

            registered = self._tools[name]
            arguments = _prepare_arguments(registered.handler, input_data)
            result = registered.handler(**arguments)
            if inspect.isawaitable(result):
                result = await result
            return ToolExecutionResult(content=_serialize_result(result))
        except Exception as exc:
            return ToolExecutionResult(
                content=(
                    f"工具 {name} 执行失败: "
                    f"{type(exc).__name__}: {exc}"
                ),
                is_error=True,
            )

    async def execute(self, name: str, input_data: dict[str, Any]) -> str:
        """执行工具并返回结果文本。"""
        result = await self.execute_with_status(name, input_data)
        return result.content


# 供 @tool 和 Agent 共用的默认注册表。
registry = ToolRegistry()
tool = registry.tool


__all__ = [
    "RegisteredTool",
    "ToolExecutionResult",
    "ToolRegistry",
    "registry",
    "tool",
]

"""根据模型用量与价格配置估算 Agent 运行费用。"""

from .config import AgentSettings
from .loop import RunStats


def estimate_cost(
    stats: RunStats,
    settings: AgentSettings,
) -> float | None:
    """估算运行费用；缺少实际用到的 token 单价时返回 None。"""
    stats = stats.aggregate()
    if (
        settings.input_price_per_million is None
        or settings.output_price_per_million is None
    ):
        return None

    if (
        stats.cache_read_input_tokens > 0
        and settings.cache_read_price_per_million is None
    ):
        return None

    if (
        stats.cache_creation_input_tokens > 0
        and settings.cache_creation_price_per_million is None
    ):
        return None

    return (
        stats.input_tokens * settings.input_price_per_million
        + stats.output_tokens * settings.output_price_per_million
        + stats.cache_read_input_tokens
        * (settings.cache_read_price_per_million or 0)
        + stats.cache_creation_input_tokens
        * (settings.cache_creation_price_per_million or 0)
    ) / 1_000_000

"""连接模型、消息上下文和工具执行的 Agent 核心流程组件。"""

import asyncio
import json
import random
import time
from collections.abc import Callable
from dataclasses import dataclass, field
from typing import Any
from uuid import uuid4

from openai import APIConnectionError, APIStatusError, AsyncOpenAI
from openai.types.chat import ChatCompletion, ChatCompletionMessage

from .context import Context
from .logging_config import get_logger


logger = get_logger("agent.loop")


@dataclass(frozen=True)
class AgentTrace:
    """标识一次运行中的主 Agent 或 SubAgent。"""

    run_id: str
    agent_id: str
    role: str
    parent_agent_id: str | None = None

    def event_context(self, turn: int | None = None) -> dict[str, Any]:
        """生成附加到结构化日志事件的关联字段。"""
        context: dict[str, Any] = {
            "run_id": self.run_id,
            "agent_id": self.agent_id,
            "role": self.role,
        }
        if self.parent_agent_id is not None:
            context["parent_agent_id"] = self.parent_agent_id
        if turn is not None:
            context["turn"] = turn
        return context


@dataclass
class RunStats:
    """记录模型调用统计，input_tokens 不包含缓存读写的输入。"""

    turns: int = 0
    input_tokens: int = 0
    output_tokens: int = 0
    cache_read_input_tokens: int = 0
    cache_creation_input_tokens: int = 0
    subagent_runs: list["RunStats"] = field(default_factory=list)

    def aggregate(self) -> "RunStats":
        """返回当前 Agent 及所有子 Agent 的汇总统计。"""
        total = RunStats(
            turns=self.turns,
            input_tokens=self.input_tokens,
            output_tokens=self.output_tokens,
            cache_read_input_tokens=self.cache_read_input_tokens,
            cache_creation_input_tokens=self.cache_creation_input_tokens,
        )
        for child in self.subagent_runs:
            child_total = child.aggregate()
            total.turns += child_total.turns
            total.input_tokens += child_total.input_tokens
            total.output_tokens += child_total.output_tokens
            total.cache_read_input_tokens += (
                child_total.cache_read_input_tokens
            )
            total.cache_creation_input_tokens += (
                child_total.cache_creation_input_tokens
            )
        return total


@dataclass(frozen=True)
class UsageTokens:
    """Normalized token usage shared by supported provider formats."""

    input_tokens: int = 0
    output_tokens: int = 0
    cache_read_input_tokens: int = 0
    cache_creation_input_tokens: int = 0


def _usage_value(source: Any, *names: str) -> Any:
    """Read the first available field from a dict or SDK object."""
    if source is None:
        return None

    for name in names:
        if isinstance(source, dict) and name in source:
            return source[name]

        value = getattr(source, name, None)
        if value is not None:
            return value

        extra = getattr(source, "model_extra", None)
        if isinstance(extra, dict) and name in extra:
            return extra[name]

    return None


def _token_count(value: Any) -> int:
    """Convert an optional token field to a non-negative integer."""
    if value is None:
        return 0
    try:
        return max(int(value), 0)
    except (TypeError, ValueError):
        return 0


def extract_usage_tokens(usage: Any) -> UsageTokens:
    """Normalize OpenAI-style and Anthropic-style usage fields."""
    details = _usage_value(usage, "prompt_tokens_details")

    cache_read = _token_count(
        _usage_value(usage, "cache_read_input_tokens", "cache_read_tokens")
    )
    if cache_read == 0:
        cache_read = _token_count(
            _usage_value(
                details,
                "cache_read_input_tokens",
                "cache_read_tokens",
                "cached_tokens",
            )
        )

    cache_creation = _token_count(
        _usage_value(
            usage,
            "cache_creation_input_tokens",
            "cache_creation_tokens",
            "cache_write_input_tokens",
        )
    )
    if cache_creation == 0:
        cache_creation = _token_count(
            _usage_value(
                details,
                "cache_creation_input_tokens",
                "cache_creation_tokens",
                "cache_write_input_tokens",
            )
        )

    explicit_input = _usage_value(usage, "input_tokens")
    prompt_tokens = _token_count(_usage_value(usage, "prompt_tokens"))
    if explicit_input is not None:
        input_tokens = _token_count(explicit_input)
    else:
        # OpenAI-style prompt_tokens commonly includes cached input.
        input_tokens = max(prompt_tokens - cache_read - cache_creation, 0)

    output_tokens = _token_count(
        _usage_value(usage, "output_tokens", "completion_tokens")
    )
    return UsageTokens(
        input_tokens=input_tokens,
        output_tokens=output_tokens,
        cache_read_input_tokens=cache_read,
        cache_creation_input_tokens=cache_creation,
    )


class MaxTurnsExceeded(RuntimeError):
    """Agent 在限定轮数内没有完成任务。"""

    def __init__(self, max_turns: int, stats: RunStats):
        super().__init__(f"Agent 达到最大轮数限制: {max_turns}")
        self.max_turns = max_turns
        self.stats = stats


class CostLimitExceeded(RuntimeError):
    """Agent 的累计模型费用超过单任务预算。"""

    def __init__(
        self,
        max_cost_usd: float,
        actual_cost_usd: float,
        stats: RunStats,
    ):
        super().__init__(
            f"Agent 费用 ${actual_cost_usd:.6f} 超过限制 "
            f"${max_cost_usd:.6f}"
        )
        self.max_cost_usd = max_cost_usd
        self.actual_cost_usd = actual_cost_usd
        self.stats = stats


@dataclass
class ToolCallTracker:
    """检测连续重复的完全相同工具调用。"""

    max_consecutive: int = 3
    _last_signature: tuple[str, str] | None = None
    _count: int = 0

    def allow(self, name: str, input_data: Any) -> bool:
        """记录一次调用，达到连续上限后拒绝执行。"""
        signature = (
            name,
            json.dumps(input_data, sort_keys=True, default=str),
        )
        if signature == self._last_signature:
            self._count += 1
        else:
            self._last_signature = signature
            self._count = 1
        return self._count < self.max_consecutive


async def run(
    client: AsyncOpenAI,
    context: Context,
    registry: Any,
    *,
    model: str,
    system_prompt: str,
    max_turns: int = 10,
    max_tokens: int = 300,
    cost_estimator: Callable[[RunStats], float | None] | None = None,
    max_cost_usd: float | None = None,
    stats: RunStats | None = None,
    trace: AgentTrace | None = None,
) -> tuple[ChatCompletion, RunStats]:
    """运行 Agent，直到模型结束或达到最大轮数。"""
    if max_cost_usd is not None:
        if max_cost_usd <= 0:
            raise ValueError("max_cost_usd 必须大于 0")
        if cost_estimator is None:
            raise ValueError("设置 max_cost_usd 时必须提供 cost_estimator")

    if trace is None:
        trace = AgentTrace(
            run_id=uuid4().hex,
            agent_id="main",
            role="main",
        )

    tools = registry.schemas()
    if stats is None:
        stats = RunStats()
    tracker = ToolCallTracker()
    logger.info(
        "Agent 开始: %s",
        trace.agent_id,
        extra={
            "event": "agent.started",
            "trace": trace.event_context(),
            "data": {
                "model": model,
                "max_turns": max_turns,
                "max_tokens": max_tokens,
                "message_count": len(context.messages),
                "tools": [tool["name"] for tool in tools],
            },
        },
    )
    for turn in range(1, max_turns + 1):
        logger.info(
            "===== 第 %s/%s 轮 =====",
            turn,
            max_turns,
            extra={
                "event": "agent.turn_started",
                "trace": trace.event_context(turn),
                "data": {"max_turns": max_turns},
            },
        )
        response = await call_llm(
            client,
            context,
            model=model,
            system_prompt=system_prompt,
            tools=tools,
            max_tokens=max_tokens,
            trace=trace,
            turn=turn,
        )
        message = response.choices[0].message
        text = message_text(message)
        if text:
            logger.info(
                "模型返回文本",
                extra={
                    "event": "agent.model_text",
                    "trace": trace.event_context(turn),
                    "console_message": f"模型文本: {text}",
                    "data": {"text": text},
                },
            )

        token_usage = extract_usage_tokens(response.usage)

        stats.turns += 1
        stats.input_tokens += token_usage.input_tokens
        stats.cache_read_input_tokens += token_usage.cache_read_input_tokens
        stats.cache_creation_input_tokens += (
            token_usage.cache_creation_input_tokens
        )
        stats.output_tokens += token_usage.output_tokens

        if max_cost_usd is not None and cost_estimator is not None:
            current_cost = cost_estimator(stats)
            if current_cost is None:
                raise ValueError("缺少完整的模型价格配置，无法执行费用熔断")
            if current_cost > max_cost_usd:
                raise CostLimitExceeded(
                    max_cost_usd=max_cost_usd,
                    actual_cost_usd=current_cost,
                    stats=stats,
                )

        context.append_assistant(assistant_message(message))

        if not message.tool_calls:
            logger.info(
                "Agent 完成: %s",
                trace.agent_id,
                extra={
                    "event": "agent.completed",
                    "trace": trace.event_context(turn),
                    "data": {
                        "turns": stats.turns,
                        "finish_reason": response.choices[0].finish_reason,
                    },
                },
            )
            return response, stats

        tool_results = await execute_tools(
            message,
            registry,
            tracker,
            trace=trace,
            turn=turn,
        )
        context.append_tool_results(tool_results)
        context.assert_paired()

    logger.error(
        "Agent 达到最大轮数: %s",
        max_turns,
        extra={
            "event": "agent.max_turns_exceeded",
            "trace": trace.event_context(max_turns),
            "data": {"max_turns": max_turns},
        },
    )
    raise MaxTurnsExceeded(max_turns, stats)


def message_text(message: ChatCompletionMessage) -> str:
    """提取响应中的 assistant 文本。"""
    return (message.content or "").strip()


def openai_tools(tools: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """把注册表的 Anthropic 风格 schema 转成 OpenAI function schema。"""
    return [
        {
            "type": "function",
            "function": {
                "name": tool["name"],
                "description": tool["description"],
                "parameters": tool["input_schema"],
            },
        }
        for tool in tools
    ]


def is_retryable_llm_error(exc: Exception) -> bool:
    """只允许网络错误、限流和服务端错误进入重试。"""
    if isinstance(exc, APIConnectionError):
        return True

    return (
        isinstance(exc, APIStatusError)
        and (exc.status_code == 429 or exc.status_code >= 500)
    )


async def call_llm(
    client: AsyncOpenAI,
    context: Context,
    *,
    model: str,
    system_prompt: str,
    tools: list[dict[str, Any]],
    max_tokens: int = 300,
    max_attempts: int = 3,
    base_delay: float = 1.0,
    trace: AgentTrace | None = None,
    turn: int | None = None,
) -> ChatCompletion:

    for attempt in range(max_attempts):
        try:
            return await client.chat.completions.create(
                model=model,
                max_tokens=max_tokens,
                messages=[
                    {"role": "system", "content": system_prompt},
                    *context.messages,
                ],
                tools=openai_tools(tools),
            )
        except (APIConnectionError, APIStatusError) as exc:
            is_last_attempt = attempt == max_attempts - 1

"""Configure plain console logs and a structured JSON event file."""

import json
import logging
import sys
from datetime import datetime
from pathlib import Path
from typing import Any


LOGGER_NAME = "agent_mini"


class ConsoleFormatter(logging.Formatter):
    """优先显示事件提供的详细控制台文本。"""

    def format(self, record: logging.LogRecord) -> str:
        return getattr(record, "console_message", record.getMessage())


class JsonEventFormatter(logging.Formatter):
    """Convert a log record to a JSON-serializable event."""

    def format_event(
        self,
        record: logging.LogRecord,
    ) -> dict[str, Any]:
        payload: dict[str, Any] = {
            "timestamp": datetime.fromtimestamp(record.created).astimezone().isoformat(
                timespec="milliseconds"
            ),
            "level": record.levelname,
            "event": getattr(record, "event", "log"),
            "message": record.getMessage(),
        }
        trace = getattr(record, "trace", None)
        if trace:
            payload["trace"] = trace
        data = getattr(record, "data", None)
        if data:
            payload["data"] = data
        if record.exc_info:
            payload["exception"] = self.formatException(record.exc_info)
        return payload


class JsonFileHandler(logging.Handler):
    """Keep the target file as one complete, readable JSON document."""

    def __init__(self, path: Path) -> None:
        super().__init__()
        self.path = path
        self.events: list[dict[str, Any]] = []
        self.event_formatter = JsonEventFormatter()
        self._write_document()

    def emit(self, record: logging.LogRecord) -> None:
        try:
            self.events.append(self.event_formatter.format_event(record))
            self._write_document()
        except Exception:
            self.handleError(record)

    def _write_document(self) -> None:
        document = {
            "schema_version": 2,
            "event_count": len(self.events),
            "events": self.events,
        }
        temporary_path = self.path.with_suffix(f"{self.path.suffix}.tmp")
        with temporary_path.open("w", encoding="utf-8") as file:
            json.dump(document, file, ensure_ascii=False, indent=2, default=str)
            file.write("\n")
        temporary_path.replace(self.path)


def get_logger(name: str) -> logging.Logger:
    """Return a child logger managed by agent-mini's logging configuration."""
    return logging.getLogger(f"{LOGGER_NAME}.{name}")


def configure_logging(log_file: Path) -> Path:
    """Clear the target file and write this run as one JSON document."""
    path = log_file.expanduser().resolve()
    path.parent.mkdir(parents=True, exist_ok=True)

    logger = logging.getLogger(LOGGER_NAME)
    logger.setLevel(logging.INFO)
    logger.propagate = False

    for handler in logger.handlers[:]:
        handler.close()
        logger.removeHandler(handler)

    console_handler = logging.StreamHandler(sys.stdout)
    console_handler.setFormatter(ConsoleFormatter())
    logger.addHandler(console_handler)

    file_handler = JsonFileHandler(path)
    logger.addHandler(file_handler)
    return path

    tools: list[dict[str, Any]],
