            )
        except (APIConnectionError, APIStatusError) as exc:
            is_last_attempt = attempt == max_attempts - 1
            if not is_retryable_llm_error(exc) or is_last_attempt:
                raise

            delay = base_delay * 2**attempt + random.uniform(0, 0.5)
            logger.warning(
                "模型请求失败，%.2f 秒后重试 (%s/%s): %s",
                delay,
                attempt + 2,
                max_attempts,
                type(exc).__name__,
                extra={
                    "event": "agent.model_retry",
                    "trace": (
                        trace.event_context(
                            turn) if trace is not None else None
                    ),
                    "data": {
                        "delay_s": delay,
                        "attempt": attempt + 2,
                        "max_attempts": max_attempts,
                        "error_type": type(exc).__name__,
                    },
                },
            )
            await asyncio.sleep(delay)

    raise RuntimeError("模型重试循环意外结束")


def assistant_message(message: ChatCompletionMessage) -> dict[str, Any]:
    """把 SDK assistant message 转成可回放的标准字典。"""
    result: dict[str, Any] = {
        "role": "assistant",
        "content": message.content,
    }
    if message.tool_calls:
        result["tool_calls"] = [
            {
                "id": tool_call.id,
                "type": "function",
                "function": {
                    "name": tool_call.function.name,
                    "arguments": tool_call.function.arguments,
                },
            }
            for tool_call in message.tool_calls
        ]
    return result


async def execute_tools(
    message: ChatCompletionMessage,
    registry: Any,
    tracker: ToolCallTracker | None = None,
    tool_timeout: float = 300.0,
    *,
    trace: AgentTrace | None = None,
    turn: int | None = None,
) -> list[dict[str, Any]]:
    """按顺序执行 function calls，并生成匹配的 tool messages。"""
    if tool_timeout <= 0:
        raise ValueError("tool_timeout 必须大于 0")

    tool_results: list[dict[str, Any]] = []
    tool_calls = message.tool_calls or []
    for tool_call in tool_calls:
        name = tool_call.function.name
        trace_context = (
            trace.event_context(turn) if trace is not None else None
        )
        try:
            input_data = json.loads(tool_call.function.arguments or "{}")
            if not isinstance(input_data, dict):
                raise TypeError("工具输入必须是 object")
        except (TypeError, json.JSONDecodeError) as exc:
            content = f"工具 {name} 参数 JSON 无效: {exc}"
            logger.error(
                content,
                extra={
                    "event": "agent.tool_invalid_arguments",
                    "trace": trace_context,
                    "data": {
                        "tool": name,
                        "status": "invalid_arguments",
                        "error": str(exc),
                    },
                },
            )
            tool_results.append(
                {
                    "role": "tool",
                    "tool_call_id": tool_call.id,
                    "content": content,
                }
            )
            continue

        if tracker is not None and not tracker.allow(name, input_data):
            content = (
                "检测到相同工具调用已连续重复 "
                f"{tracker.max_consecutive} 次，请停止重复调用并采取下一步行动。"
            )
            logger.warning(
                "拦截重复调用: %s %s",
                name,
                input_data,
                extra={
                    "event": "agent.tool_blocked",
                    "trace": trace_context,
                    "data": {
                        "tool": name,
                        "status": "blocked",
                        "arguments": input_data,
                    },
                },
            )
        else:
            logger.info(
                "工具开始: %s",
                name,
                extra={
                    "event": "agent.tool_started",
                    "trace": trace_context,
                    "console_message": f"调用工具: {name} {input_data}",
                    "data": {
                        "tool": name,
                        "arguments": input_data,
                    },
                },
            )
            try:
                execution = await asyncio.wait_for(
                    registry.execute_with_status(name, input_data),
                    timeout=tool_timeout,
                )
                content = execution.content
                status = "error" if execution.is_error else "ok"
            except TimeoutError:
                content = (
                    f"工具 {name} 执行超时（超过 {tool_timeout:g} 秒）"
                )
                status = "timeout"
            logger.info(
                "工具完成: %s (%s)",
                name,
                status,
                extra={
                    "event": "agent.tool_completed",
                    "trace": trace_context,
                    "console_message": f"工具结果: {content}",
                    "data": {
                        "tool": name,
                        "status": status,
                        "content": content,
                    },
                },
            )

        tool_results.append(
            {
                "role": "tool",
                "tool_call_id": tool_call.id,
                "content": content,
            }
        )
    return tool_results

"""维护可直接发送给 Chat Completions API 的完整对话历史。"""

from typing import Any


class Context:
    """保存 user、assistant 和 tool 消息，并校验工具调用配对。"""

    def __init__(self) -> None:
        self.messages: list[dict[str, Any]] = []

    def append_user(self, text: str) -> None:
        """追加用户文本消息。"""
        self.messages.append({"role": "user", "content": text})

    def append_assistant(self, message: dict[str, Any]) -> None:
        """追加完整 assistant 消息，包括 tool_calls。"""
        self.messages.append(message)

    def append_tool_results(self, tool_results: list[dict[str, Any]]) -> None:
        """追加与上一条 assistant tool_calls 对应的 tool 消息。"""
        self.messages.extend(tool_results)

    def assert_paired(self) -> None:
        """校验每个 assistant tool_call 都有唯一匹配的 tool result。"""
        pending_ids: set[str] = set()
        seen_ids: set[str] = set()

        for message in self.messages:
            role = message.get("role")
            if role not in {"user", "assistant", "tool"}:
                raise RuntimeError(f"未知消息角色: {role}")

            if role == "assistant":
                if pending_ids:
                    raise RuntimeError("上一轮 tool_calls 缺少对应的 tool result")
                for tool_call in message.get("tool_calls") or []:
                    tool_call_id = tool_call.get("id")
                    if not isinstance(tool_call_id, str) or not tool_call_id:
                        raise RuntimeError("tool_call 缺少有效 id")
                    if tool_call_id in seen_ids:
                        raise RuntimeError(f"tool_call id 重复: {tool_call_id}")
                    pending_ids.add(tool_call_id)
                    seen_ids.add(tool_call_id)
                continue

            if role == "user":
                if pending_ids:
                    raise RuntimeError("tool_calls 后出现了普通 user 消息")
                continue

            tool_call_id = message.get("tool_call_id")
            if not isinstance(tool_call_id, str) or not tool_call_id:
                raise RuntimeError("tool result 缺少有效 tool_call_id")
            if tool_call_id not in pending_ids:
                raise RuntimeError(
                    f"tool result 没有匹配的 tool_call: {tool_call_id}"
                )
            pending_ids.remove(tool_call_id)

        if pending_ids:
            missing = ", ".join(sorted(pending_ids))
            raise RuntimeError(f"对话结束时仍有未配对的 tool_call: {missing}")

"""把 Python 函数注册为模型可调用工具，并统一校验和执行。"""

from __future__ import annotations

import inspect
import json
import re
from copy import deepcopy
from dataclasses import dataclass
from typing import Any, Callable, get_type_hints

from pydantic import BaseModel, TypeAdapter


ToolHandler = Callable[..., Any]


@dataclass(frozen=True)
class RegisteredTool:
    """已注册工具的定义和处理函数。"""

    name: str
    description: str
    input_schema: dict[str, Any]
    handler: ToolHandler


@dataclass(frozen=True)
class ToolExecutionResult:
    """工具执行结果。"""

    content: str
    is_error: bool = False


def _parse_docstring(handler: ToolHandler) -> tuple[str, dict[str, str]]:
    """从 docstring 提取工具描述和参数描述。"""
    doc = inspect.getdoc(handler) or ""
    description_lines: list[str] = []
    argument_descriptions: dict[str, str] = {}
    in_args = False
    current_argument: str | None = None

    for raw_line in doc.splitlines():
        line = raw_line.strip()
        if line in {"Args:", "Arguments:", "Parameters:"}:
            in_args = True
            current_argument = None
            continue
        if line in {"Returns:", "Raises:", "Examples:", "Example:"}:
            in_args = False
            current_argument = None
            continue

        if not in_args:
            if line:
                description_lines.append(line)
            continue

        match = re.match(r"^(\w+)(?:\s*\([^)]*\))?\s*:\s*(.*)$", line)
        if match:
            current_argument = match.group(1)
            argument_descriptions[current_argument] = match.group(2)
        elif current_argument and line:
            argument_descriptions[current_argument] += f" {line}"

    description = " ".join(description_lines).strip() or handler.__name__
    return description, argument_descriptions


def _parameters(handler: ToolHandler) -> list[inspect.Parameter]:
    """读取可由 JSON object 传入的具名参数。"""
    parameters = list(inspect.signature(handler).parameters.values())
    unsupported = {
        inspect.Parameter.POSITIONAL_ONLY,
        inspect.Parameter.VAR_POSITIONAL,
        inspect.Parameter.VAR_KEYWORD,
    }
    if any(parameter.kind in unsupported for parameter in parameters):
        raise TypeError("工具函数只支持普通具名参数和关键字参数")
    return parameters


def _type_hints(handler: ToolHandler) -> dict[str, Any]:
    """安全读取函数类型标注。"""
    try:
        return get_type_hints(handler)
    except (NameError, TypeError):
        return {}


def _is_model_type(annotation: Any) -> bool:
    return inspect.isclass(annotation) and issubclass(annotation, BaseModel)


def _schema_for(annotation: Any) -> dict[str, Any]:
    """把类型标注转成 JSON Schema。"""
    if annotation is inspect.Signature.empty or annotation is Any:
        return {}
    try:
        return TypeAdapter(annotation).json_schema()
    except Exception:
        return {}


def _build_definition(
    handler: ToolHandler,
) -> tuple[str, dict[str, Any]]:
    """生成工具描述和输入 schema。"""
    description, argument_descriptions = _parse_docstring(handler)
    parameters = _parameters(handler)
    type_hints = _type_hints(handler)

    # 单个 Pydantic 参数直接使用模型 schema。
    if len(parameters) == 1:
        parameter = parameters[0]
        annotation = type_hints.get(parameter.name, parameter.annotation)
        if _is_model_type(annotation):
            return description, annotation.model_json_schema()

    # 普通参数逐个生成 properties 和 required。
    properties: dict[str, Any] = {}
    required: list[str] = []
    for parameter in parameters:
        annotation = type_hints.get(parameter.name, parameter.annotation)
        property_schema = _schema_for(annotation)
        parameter_description = argument_descriptions.get(parameter.name)
        if parameter_description:
            property_schema["description"] = parameter_description
        properties[parameter.name] = property_schema

        if parameter.default is inspect.Signature.empty:
            required.append(parameter.name)

    input_schema: dict[str, Any] = {
        "type": "object",
        "properties": properties,
    }
    if required:
        input_schema["required"] = required
    return description, input_schema


def _prepare_arguments(
    handler: ToolHandler,
    input_data: dict[str, Any],
) -> dict[str, Any]:
    """校验模型输入并生成工具调用参数。"""
    signature = inspect.signature(handler)
    parameters = _parameters(handler)
    type_hints = _type_hints(handler)

    if len(parameters) == 1:
        parameter = parameters[0]
        annotation = type_hints.get(parameter.name, parameter.annotation)
        if _is_model_type(annotation):
            return {parameter.name: annotation.model_validate(input_data)}

    known_names = {parameter.name for parameter in parameters}
    unexpected = sorted(set(input_data) - known_names)
    if unexpected:
        raise TypeError(f"未知工具参数: {', '.join(unexpected)}")

    arguments: dict[str, Any] = {}
    for parameter in parameters:
        if parameter.name not in input_data:
            continue
        annotation = type_hints.get(parameter.name, parameter.annotation)
        value = input_data[parameter.name]
        if annotation is not inspect.Signature.empty and annotation is not Any:
            value = TypeAdapter(annotation).validate_python(value)
        arguments[parameter.name] = value

    signature.bind(**arguments)
    return arguments


def _serialize_result(result: Any) -> str:
    """把工具返回值转成文本。"""
    if isinstance(result, str):
        return result
    return json.dumps(result, ensure_ascii=False, default=str)


class ToolRegistry:
    """管理工具注册、schema 导出和执行。"""

    def __init__(self) -> None:
        self._tools: dict[str, RegisteredTool] = {}

    def register(
        self,
        handler: ToolHandler,
        *,
        name: str | None = None,
        description: str | None = None,
        input_schema: dict[str, Any] | None = None,
    ) -> ToolHandler:
        """注册工具，缺省信息从函数定义生成。"""
        tool_name = name or handler.__name__
        if tool_name in self._tools:
            raise ValueError(f"工具已注册: {tool_name}")
        generated_description, generated_schema = _build_definition(handler)
        self._tools[tool_name] = RegisteredTool(
            name=tool_name,
            description=description or generated_description,
            input_schema=input_schema or generated_schema,
            handler=handler,
        )
        return handler

    def tool(
        self,
        handler: ToolHandler | None = None,
        *,
        name: str | None = None,
        description: str | None = None,
        input_schema: dict[str, Any] | None = None,
    ) -> ToolHandler | Callable[[ToolHandler], ToolHandler]:
        """支持 `@tool` 和 `@tool(...)` 两种装饰器写法。"""
        def decorator(function: ToolHandler) -> ToolHandler:
            return self.register(
                function,
                name=name,
                description=description,
                input_schema=input_schema,
            )

        if handler is None:
            return decorator
        return decorator(handler)

    def schemas(self) -> list[dict[str, Any]]:
        """导出 Messages API 使用的工具 schema。"""
        return [
            {
                "name": registered.name,
                "description": registered.description,
                "input_schema": deepcopy(registered.input_schema),
            }
            for registered in self._tools.values()
        ]

    async def execute_with_status(
        self,
        name: str,
        input_data: dict[str, Any],
    ) -> ToolExecutionResult:
        """执行工具；异常转成 is_error 结果供模型继续处理。"""
        try:
            if not isinstance(input_data, dict):
                raise TypeError("工具输入必须是 object")
            if name not in self._tools:
                raise KeyError(f"未注册工具: {name}")

            registered = self._tools[name]
            arguments = _prepare_arguments(registered.handler, input_data)
            result = registered.handler(**arguments)
            if inspect.isawaitable(result):
                result = await result

"""根据模型用量与价格配置估算 Agent 运行费用。"""

from .config import AgentSettings
from .loop import RunStats


def estimate_cost(
    stats: RunStats,
    settings: AgentSettings,
) -> float | None:
    """估算运行费用；缺少实际用到的 token 单价时返回 None。"""
    stats = stats.aggregate()
    if (
        settings.input_price_per_million is None
        or settings.output_price_per_million is None
    ):
        return None

    if (
        stats.cache_read_input_tokens > 0
        and settings.cache_read_price_per_million is None
    ):
        return None

    if (
        stats.cache_creation_input_tokens > 0
        and settings.cache_creation_price_per_million is None
    ):
        return None

    return (
        stats.input_tokens * settings.input_price_per_million
        + stats.output_tokens * settings.output_price_per_million
        + stats.cache_read_input_tokens
        * (settings.cache_read_price_per_million or 0)
        + stats.cache_creation_input_tokens
        * (settings.cache_creation_price_per_million or 0)
    ) / 1_000_000

"""Configure plain console logs and a structured JSON event file."""

import json
import logging
import sys
from datetime import datetime
from pathlib import Path
from typing import Any


LOGGER_NAME = "agent_mini"


class ConsoleFormatter(logging.Formatter):
    """优先显示事件提供的详细控制台文本。"""

    def format(self, record: logging.LogRecord) -> str:
        return getattr(record, "console_message", record.getMessage())


class JsonEventFormatter(logging.Formatter):
    """Convert a log record to a JSON-serializable event."""

    def format_event(
        self,
        record: logging.LogRecord,
    ) -> dict[str, Any]:
        payload: dict[str, Any] = {
            "timestamp": datetime.fromtimestamp(record.created).astimezone().isoformat(
                timespec="milliseconds"
            ),
            "level": record.levelname,
            "event": getattr(record, "event", "log"),
            "message": record.getMessage(),
        }
        trace = getattr(record, "trace", None)
        if trace:
            payload["trace"] = trace
        data = getattr(record, "data", None)
        if data:
            payload["data"] = data
        if record.exc_info:
            payload["exception"] = self.formatException(record.exc_info)
        return payload


class JsonFileHandler(logging.Handler):
    """Keep the target file as one complete, readable JSON document."""

    def __init__(self, path: Path) -> None:
        super().__init__()
        self.path = path
        self.events: list[dict[str, Any]] = []
        self.event_formatter = JsonEventFormatter()
        self._write_document()

    def emit(self, record: logging.LogRecord) -> None:
        try:
            self.events.append(self.event_formatter.format_event(record))
            self._write_document()
        except Exception:
            self.handleError(record)

    def _write_document(self) -> None:
        document = {
            "schema_version": 2,
            "event_count": len(self.events),
            "events": self.events,
        }
        temporary_path = self.path.with_suffix(f"{self.path.suffix}.tmp")
        with temporary_path.open("w", encoding="utf-8") as file:
            json.dump(document, file, ensure_ascii=False, indent=2, default=str)
            file.write("\n")
        temporary_path.replace(self.path)


def get_logger(name: str) -> logging.Logger:
    """Return a child logger managed by agent-mini's logging configuration."""
    return logging.getLogger(f"{LOGGER_NAME}.{name}")


def configure_logging(log_file: Path) -> Path:
    """Clear the target file and write this run as one JSON document."""
    path = log_file.expanduser().resolve()
    path.parent.mkdir(parents=True, exist_ok=True)

    logger = logging.getLogger(LOGGER_NAME)
    logger.setLevel(logging.INFO)
    logger.propagate = False

    for handler in logger.handlers[:]:
        handler.close()
        logger.removeHandler(handler)

    console_handler = logging.StreamHandler(sys.stdout)
    console_handler.setFormatter(ConsoleFormatter())
    logger.addHandler(console_handler)

    file_handler = JsonFileHandler(path)
    logger.addHandler(file_handler)
    return path

