                    "event": "agent.tool_blocked",
                    "trace": trace_context,
                    "data": {
                        "tool": name,
                        "status": "blocked",
                        "arguments": input_data,
                    },
                },
            )
        else:
            logger.info(
                "工具开始: %s",
                name,
                extra={
                    "event": "agent.tool_started",
                    "trace": trace_context,
                    "console_message": f"调用工具: {name} {input_data}",
                    "data": {
                        "tool": name,
                        "arguments": input_data,
                    },
                },
            )
            try:
                execution = await asyncio.wait_for(
                    registry.execute_with_status(name, input_data),
                    timeout=tool_timeout,
                )
                content = execution.content
                status = "error" if execution.is_error else "ok"
            except TimeoutError:
                content = (
                    f"工具 {name} 执行超时（超过 {tool_timeout:g} 秒）"
                )
                status = "timeout"
            logger.info(
                "工具完成: %s (%s)",
                name,
                status,
                extra={
                    "event": "agent.tool_completed",
                    "trace": trace_context,
                    "console_message": f"工具结果: {content}",
                    "data": {
                        "tool": name,
                        "status": status,
                        "content": content,
                    },
                },
            )

        tool_results.append(
            {
                "role": "tool",
                "tool_call_id": tool_call.id,
                "content": content,
            }
        )
    return tool_results

            }
            for registered in self._tools.values()
        ]

    async def execute_with_status(
        self,
        name: str,
        input_data: dict[str, Any],
    ) -> ToolExecutionResult:
        """执行工具；异常转成 is_error 结果供模型继续处理。"""
        try:
            if not isinstance(input_data, dict):
                raise TypeError("工具输入必须是 object")
            if name not in self._tools:
                raise KeyError(f"未注册工具: {name}")

            registered = self._tools[name]
            arguments = _prepare_arguments(registered.handler, input_data)
            result = registered.handler(**arguments)
            if inspect.isawaitable(result):
                result = await result
            return ToolExecutionResult(content=_serialize_result(result))
        except Exception as exc:
            return ToolExecutionResult(
                content=(
                    f"工具 {name} 执行失败: "
                    f"{type(exc).__name__}: {exc}"
                ),
                is_error=True,
            )

    async def execute(self, name: str, input_data: dict[str, Any]) -> str:
        """执行工具并返回结果文本。"""
        result = await self.execute_with_status(name, input_data)
        return result.content


